(917473, 105272, 12962, '<td valign="top">I like the freedom represented in this photograph ... ahh, the carefree days of youth and summer ... 10.</td>', 'I like the freedom represented in this photograph ... ahh, the carefree days of youth and summer ... 10.', '2004-09-20 02:41:42.000000', NULL, 1),
(917476, 106355, 12962, '<td valign="top">Perfect - timing, balance, composition, colors, post processing and fit for the challenge.  It''s one of those photographs that just ... is. 10.</td>', 'Perfect - timing, balance, composition, colors, post processing and fit for the challenge.  It''s one of those photographs that just ... is. 10.', '2004-09-20 02:45:50.000000', NULL, 1),
(917478, 106191, 12962, '<td valign="top">Beautiful colors and good use of negative space.  Fit for a Minolta ad.  Good job!</td>', 'Beautiful colors and good use of negative space.  Fit for a Minolta ad.  Good job!', '2004-09-20 02:47:35.000000', NULL, 1),
(917479, 105836, 12962, '<td valign="top">Ever so slight motion blur ... but the capture is beautiful, the placement is appropriate - the space on the right gives room for the bird to fly into.</td>', 'Ever so slight motion blur ... but the capture is beautiful, the placement is appropriate - the space on the right gives room for the bird to fly into.', '2004-09-20 02:48:53.000000', NULL, 1),
(917480, 106207, 12962, '<td valign="top">That looks sooo refrrrreshing!  Nice capture!</td>', 'That looks sooo refrrrreshing!  Nice capture!', '2004-09-20 02:49:51.000000', NULL, 1),
(917481, 106309, 12962, '<td valign="top">Wonderful tableau.  To me, a more focused frame like two to four elephants or boys (for example, the first four elephants) instead of this wide angle would have been more effective.  The last elephants on the right no longer give more information.  But it is a good example of stopped motion.</td>', 'Wonderful tableau.  To me, a more focused frame like two to four elephants or boys (for example, the first four elephants) instead of this wide angle would have been more effective.  The last elephants on the right no longer give more information.  But it is a good example of stopped motion.', '2004-09-20 02:54:09.000000', NULL, 1),
(917482, 105576, 12962, '<td valign="top">The sparks are beautiful.</td>', 'The sparks are beautiful.', '2004-09-20 02:56:10.000000', NULL, 1),
(917487, 105814, 12962, '<td valign="top">Blurring on the wings tells me this is not stopped motion.  It''s a pity because the composition and color are wonderful.</td>', 'Blurring on the wings tells me this is not stopped motion.  It''s a pity because the composition and color are wonderful.', '2004-09-20 02:57:54.000000', NULL, 1),
(917488, 106098, 12962, '<td valign="top">Cool effect of the contrasting colors and lighting.</td>', 'Cool effect of the contrasting colors and lighting.', '2004-09-20 02:58:25.000000', NULL, 1),
(917490, 106154, 12962, '<td valign="top">Blurring is not stopped motion.  It''s a pity because the composition is beautiful and the stance is very dynamic.</td>', 'Blurring is not stopped motion.  It''s a pity because the composition is beautiful and the stance is very dynamic.', '2004-09-20 02:59:49.000000', NULL, 1),
(917493, 106314, 12962, '<td valign="top">Every so slight blur of the ball - not stopped motion.  The expression of the child is priceless though.</td>', 'Every so slight blur of the ball - not stopped motion.  The expression of the child is priceless though.', '2004-09-20 03:00:52.000000', NULL, 1),
(917496, 105675, 12962, '<td valign="top">Wow!  Beautiful physics experiment.  An intersection of art and science.</td>', 'Wow!  Beautiful physics experiment.  An intersection of art and science.', '2004-09-20 03:01:28.000000', NULL, 1),
(917499, 105499, 12962, '<td valign="top">Nice ... very nice.  Problematic though because this was supposed to be stopped motion.</td>', 'Nice ... very nice.  Problematic though because this was supposed to be stopped motion.', '2004-09-20 03:02:48.000000', NULL, 1),
(917502, 105171, 12962, '<td valign="top">Terrific mid-air capture.</td>', 'Terrific mid-air capture.', '2004-09-20 03:03:38.000000', NULL, 1),
(917505, 106357, 12962, '<td valign="top">Every so slight blur of the hand, especially the right hand = not stopped motion.  Beautiful colors and composition and choice of setting.  Primary colors really work here.</td>', 'Every so slight blur of the hand, especially the right hand = not stopped motion.  Beautiful colors and composition and choice of setting.  Primary colors really work here.', '2004-09-20 03:04:37.000000', NULL, 1),
(917507, 106187, 12962, '<td valign="top">A mild pass through NeatImage or similar programs would have lessened the graininess unless you wanted the grain effect.  Lovely colors ... very electric!</td>', 'A mild pass through NeatImage or similar programs would have lessened the graininess unless you wanted the grain effect.  Lovely colors ... very electric!', '2004-09-20 03:05:50.000000', NULL, 1),
