(917621, 106235, 19952, '<td valign="top">Excellent vantage point and a great motion capture. This is a really nice shot for this challenge.</td>', 'Excellent vantage point and a great motion capture. This is a really nice shot for this challenge.', '2004-09-20 04:55:40.000000', NULL, 1),
(917626, 106111, 19952, '<td valign="top">This is a really nice take on a popular theme. The idea is nice and the composition and motion capture are really outstanding. Great job.</td>', 'This is a really nice take on a popular theme. The idea is nice and the composition and motion capture are really outstanding. Great job.', '2004-09-20 04:58:26.000000', NULL, 1),
(917631, 106309, 19952, '<td valign="top">This is one of the better people-jumping-on-elephants shots I''ve seen in this challenge. ;-)The subject is very interesting and appropriate for this challenge and the composition is nice, but the shot is a bit dark and perhaps a little over-sharpened. It also might be nice to zoom in on about half of these people/elephants to get a bit more detail. Still this is a nice photo - good job.</td>', 'This is one of the better people-jumping-on-elephants shots I''ve seen in this challenge. ;-)The subject is very interesting and appropriate for this challenge and the composition is nice, but the shot is a bit dark and perhaps a little over-sharpened. It also might be nice to zoom in on about half of these people/elephants to get a bit more detail. Still this is a nice photo - good job.', '2004-09-20 05:05:41.000000', NULL, 1),
(917636, 106224, 19952, '<td valign="top">Even through the backstop, this is a nice motion capture with good color and clarity. Very nice shot and a good picture for this challenge.</td>', 'Even through the backstop, this is a nice motion capture with good color and clarity. Very nice shot and a good picture for this challenge.', '2004-09-20 05:09:22.000000', NULL, 1),
(917639, 105675, 19952, '<td valign="top">You certainly win the award for the fastest action captured in a photo. :-) And this is a nice, simple, colorful shot of an interesting subject. Very nice job.</td>', 'You certainly win the award for the fastest action captured in a photo. :-) And this is a nice, simple, colorful shot of an interesting subject. Very nice job.', '2004-09-20 05:12:17.000000', NULL, 1),
(917640, 105791, 19952, '<td valign="top">Excellent motion capture and nice colors without blowing out all the white parts. Very nice shot.</td>', 'Excellent motion capture and nice colors without blowing out all the white parts. Very nice shot.', '2004-09-20 05:13:35.000000', NULL, 1),
