(917764, 106328, 24459, '<td valign="top">Very nice picture. I would give it a 10 if it was from the other side (seeing the bird''s face) :)</td>', 'Very nice picture. I would give it a 10 if it was from the other side (seeing the bird''s face) :)', '2004-09-20 07:37:48.000000', NULL, 1),
(917765, 105708, 9232, '<td valign="top">Good idea.  Different from most shots in challenge.  I like the angle you selected but think that widening the shot out a little to include all the racket head would have made this a slightly stronger composition.  It looks like you had some fairly strong light here as the details along the arm seem blown out; the face and white shirt, however, retain some detail and those are the more important elements IMO.  Nice use of DoF to direct the viewer''s attention to the subject''s face.</td>', 'Good idea.  Different from most shots in challenge.  I like the angle you selected but think that widening the shot out a little to include all the racket head would have made this a slightly stronger composition.  It looks like you had some fairly strong light here as the details along the arm seem blown out; the face and white shirt, however, retain some detail and those are the more important elements IMO.  Nice use of DoF to direct the viewer''s attention to the subject''s face.', '2004-09-20 07:38:01.000000', NULL, 1),
(917766, 105730, 24459, '<td valign="top">Beautifull shot. Outstanding</td>', 'Beautifull shot. Outstanding', '2004-09-20 07:38:41.000000', NULL, 1),
(917767, 106183, 24459, '<td valign="top">Love the colours of fruits. Well done.</td>', 'Love the colours of fruits. Well done.', '2004-09-20 07:39:30.000000', NULL, 1),
(917768, 106326, 24459, '<td valign="top">Finally an interesting splash :)</td>', 'Finally an interesting splash :)', '2004-09-20 07:40:05.000000', NULL, 1),
(917770, 106205, 9232, '<td valign="top">Great exposure on the sky.  The subject has some harsh shadows but I think it works in this composition.  I like the use of the space (is it truly negative space with the clouds providing a background of interest that the viewer can peruse?).  I wish the subject were just a litlte higher in the composition to put the red helmet closer to the junction of the top and righthand thirds lines; as it is he seems to be almost centered top-to-bottom.  <br/>Everytime I look away and look back I notice the rider.  This is a solid composition; the subject really pops out of this shot with action.  Did you enhance the contrast on the bike rider?</td>', 'Great exposure on the sky.  The subject has some harsh shadows but I think it works in this composition.  I like the use of the space (is it truly negative space with the clouds providing a background of interest that the viewer can peruse?).  I wish the subject were just a litlte higher in the composition to put the red helmet closer to the junction of the top and righthand thirds lines; as it is he seems to be almost centered top-to-bottom.  Everytime I look away and look back I notice the rider.  This is a solid composition; the subject really pops out of this shot with action.  Did you enhance the contrast on the bike rider?', '2004-09-20 07:41:44.000000', NULL, 1),
(917771, 106208, 9232, '<td valign="top">I wish the composition wasn''t so tight on the subject because it looks like the water droplets all the way around the photo extend beyond the border of the shot.  Then again, a woman in a t-shirt falling into a pool?  Nice composition.  ;)<br/>I do like the exposure you got here.  The water on the sides has details and you didn''t lose the details in the darker jeans or the white shirt.</td>', 'I wish the composition wasn''t so tight on the subject because it looks like the water droplets all the way around the photo extend beyond the border of the shot.  Then again, a woman in a t-shirt falling into a pool?  Nice composition.  ;)I do like the exposure you got here.  The water on the sides has details and you didn''t lose the details in the darker jeans or the white shirt.', '2004-09-20 07:44:05.000000', NULL, 1),
(917772, 106365, 24459, '<td valign="top">There''s something wrong with the background. I think it could be whiter or.. I dn''t know, but I really don''t like it. And the drop seems to disappear. It gets no viewer''s attraction</td>', 'There''s something wrong with the background. I think it could be whiter or.. I dn''t know, but I really don''t like it. And the drop seems to disappear. It gets no viewer''s attraction', '2004-09-20 07:44:42.000000', NULL, 1),
(917774, 106009, 24459, '<td valign="top">The picture is too dark. Should have do a bit of postprocessing to make the colours better. After all this is a members challenge</td>', 'The picture is too dark. Should have do a bit of postprocessing to make the colours better. After all this is a members challenge', '2004-09-20 07:46:23.000000', NULL, 1),
(917775, 105515, 9232, '<td valign="top">Great subject but it feels just a little soft especially around the rocks.  It looks like this was shot pretty late or early in the day as the light has a color cast and seems to be coming from low on the horizon.  I wonder what shutter speed and aperture you used on this shot.  <br/>Great choice of subjects.  Wish I''d been there with you on this shoot.</td>', 'Great subject but it feels just a little soft especially around the rocks.  It looks like this was shot pretty late or early in the day as the light has a color cast and seems to be coming from low on the horizon.  I wonder what shutter speed and aperture you used on this shot.  Great choice of subjects.  Wish I''d been there with you on this shoot.', '2004-09-20 07:46:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(917776, 106359, 24459, '<td valign="top">The tiger doesn''t seem to be moving at all. Appart from yawning of course. would prefer to see it run</td>', 'The tiger doesn''t seem to be moving at all. Appart from yawning of course. would prefer to see it run', '2004-09-20 07:47:55.000000', NULL, 1),
(917777, 105871, 24459, '<td valign="top">This car seems to be stopped and doen''t move at all. Specially that I can see the reflection of you, and guess you would be dead by now if the car was actually going</td>', 'This car seems to be stopped and doen''t move at all. Specially that I can see the reflection of you, and guess you would be dead by now if the car was actually going', '2004-09-20 07:49:30.000000', NULL, 1),
(917778, 105631, 24459, '<td valign="top">Nice picture but no invention nor creativity. Seen plenty of those in this challenge and in the Stopped Motion I as well.</td>', 'Nice picture but no invention nor creativity. Seen plenty of those in this challenge and in the Stopped Motion I as well.', '2004-09-20 07:50:53.000000', NULL, 1),
(917780, 106340, 24459, '<td valign="top">I expected water drops, splashes, people juming, birds etc. but a nunning race pig is way beyond my expectations! And a great quality one too. You diserve a 10</td>', 'I expected water drops, splashes, people juming, birds etc. but a nunning race pig is way beyond my expectations! And a great quality one too. You diserve a 10', '2004-09-20 07:52:02.000000', NULL, 1),
(917781, 106208, 24459, '<td valign="top">How many tries did it take ? lol :)  I loke it. great timing</td>', 'How many tries did it take ? lol :)  I loke it. great timing', '2004-09-20 07:52:56.000000', NULL, 1),
(917782, 106293, 26115, '<td valign="top">very nice photo, lovely composition and focus!   interesting photo from the wings as well       only aspect i might change is the dimensions of the photo.... being a rather light background it looks rather boxy when maybe a more elongated rectangle with give more dimensions and "room for you birds to move"     but thats a personal opinion and does not cloud your photo whatsoever...       gr8 shot once again!</td>', 'very nice photo, lovely composition and focus!   interesting photo from the wings as well       only aspect i might change is the dimensions of the photo.... being a rather light background it looks rather boxy when maybe a more elongated rectangle with give more dimensions and "room for you birds to move"     but thats a personal opinion and does not cloud your photo whatsoever...       gr8 shot once again!', '2004-09-20 07:53:52.000000', NULL, 1),
(917785, 106183, 9232, '<td valign="top">Great composition.  I''m not sure whether I like the square crop on this or not.  Perhaps a portrait crop would have lent a sense of gravity to the cascade of objects.  Regardless you chose a wonderful background and I love the interplay of the blue gradient sky in the background with the gray shirt of the subject.  Am I seeing some moire in the shirt or is that a textured pattern?  Your exposure looks like it was difficult.  The shadows cast on the subject are hard and the hot spots on the subject''s cheek and fingertips tend to show that you probably had some difficult lighting to work with.  The exposure on the all the fruit still allows some texture and details to show through; the texture of the lighter, more reflective oranges and the contours of the duller peppers show a nice range.  I wonder what camera you used and what settings allowed you to get such a good exposure with strong directional light like this.<br/>You did a good job catching the action here.  Your subject is personable, perhaps its the backwards facing cap or maybe just the fountain of fruit but I can imagine him to be a brother or uncle who is just showing off at a family get together and making the kids laugh.  The shot seems playful and yet it looks technically diffcult.<br/> <br/>Good job.</td>', 'Great composition.  I''m not sure whether I like the square crop on this or not.  Perhaps a portrait crop would have lent a sense of gravity to the cascade of objects.  Regardless you chose a wonderful background and I love the interplay of the blue gradient sky in the background with the gray shirt of the subject.  Am I seeing some moire in the shirt or is that a textured pattern?  Your exposure looks like it was difficult.  The shadows cast on the subject are hard and the hot spots on the subject''s cheek and fingertips tend to show that you probably had some difficult lighting to work with.  The exposure on the all the fruit still allows some texture and details to show through; the texture of the lighter, more reflective oranges and the contours of the duller peppers show a nice range.  I wonder what camera you used and what settings allowed you to get such a good exposure with strong directional light like this.You did a good job catching the action here.  Your subject is personable, perhaps its the backwards facing cap or maybe just the fountain of fruit but I can imagine him to be a brother or uncle who is just showing off at a family get together and making the kids laugh.  The shot seems playful and yet it looks technically diffcult. Good job.', '2004-09-20 07:56:56.000000', NULL, 1),
(917792, 106321, 13602, '<td valign="top">Verry good image, I like the framing verry much! good luck!</td>', 'Verry good image, I like the framing verry much! good luck!', '2004-09-20 08:03:39.000000', NULL, 1),
(917795, 105730, 13602, '<td valign="top">Excellent, I like this one, I wonder how many others get it. Good luck!</td>', 'Excellent, I like this one, I wonder how many others get it. Good luck!', '2004-09-20 08:04:54.000000', NULL, 1),
(917796, 105971, 13602, '<td valign="top">This image is verry beautiful, verry well framed, but I''m not sure for meeting the challenge. In a stopped motion challenge you kinda expect things that usualy move faster to be stopped. But again this is a wonderful picture. 9</td>', 'This image is verry beautiful, verry well framed, but I''m not sure for meeting the challenge. In a stopped motion challenge you kinda expect things that usualy move faster to be stopped. But again this is a wonderful picture. 9', '2004-09-20 08:06:53.000000', NULL, 1),
(917800, 106050, 13602, '<td valign="top">Wonderful image, I think the angle is a bit too frontal, would of been so much better with a bit of a side angle.</td>', 'Wonderful image, I think the angle is a bit too frontal, would of been so much better with a bit of a side angle.', '2004-09-20 08:10:02.000000', NULL, 1),
(917807, 106055, 2344, '<td valign="top">I love this photo but I hate the fact that it''s super over sharpened. it totally takes away from the image.  I would have given this a 9 but I''m gonna give it a 5 instead.</td>', 'I love this photo but I hate the fact that it''s super over sharpened. it totally takes away from the image.  I would have given this a 9 but I''m gonna give it a 5 instead.', '2004-09-20 08:18:40.000000', NULL, 1),
