(918179, 106362, 5822, '<td valign="top">I Like this shot a lot! Really interesting subject matter. While the colors are nicely saturated, I think it''s a bit dark and would liked to have seen it a bit closer up with a higher focal length even to the point of cropping out the right side of the photo, as this area is the darkest and also has the distracting flag and sign.</td>', 'I Like this shot a lot! Really interesting subject matter. While the colors are nicely saturated, I think it''s a bit dark and would liked to have seen it a bit closer up with a higher focal length even to the point of cropping out the right side of the photo, as this area is the darkest and also has the distracting flag and sign.', '2004-09-20 13:17:38.000000', NULL, 1),
(918180, 105171, 18197, '<td valign="top">Good image but a bit over sharpened.</td>', 'Good image but a bit over sharpened.', '2004-09-20 13:17:59.000000', NULL, 1),
(918183, 106208, 25754, '<td valign="top">Excellent :)</td>', 'Excellent :)', '2004-09-20 13:19:35.000000', NULL, 1),
(918185, 105730, 25754, '<td valign="top">Very creative, and you got this just at the right moment! I like this very much.</td>', 'Very creative, and you got this just at the right moment! I like this very much.', '2004-09-20 13:20:58.000000', NULL, 1),
(918189, 105814, 16488, '<td valign="top">I like the way the light catches the wing feathers and the cobblestone background adds interest.  I wish the head was more present.  The bird looks slightly decapitated.  Not a "perfect" stop action as there is motion blur, but if it weren''t in the challenge description it wouldn''t bother me at all.  Nice choice.  Interesting shape.</td>', 'I like the way the light catches the wing feathers and the cobblestone background adds interest.  I wish the head was more present.  The bird looks slightly decapitated.  Not a "perfect" stop action as there is motion blur, but if it weren''t in the challenge description it wouldn''t bother me at all.  Nice choice.  Interesting shape.', '2004-09-20 13:23:26.000000', NULL, 1),
(918191, 106293, 25754, '<td valign="top">This is an amazing shot.</td>', 'This is an amazing shot.', '2004-09-20 13:24:42.000000', NULL, 1),
(918192, 106232, 16488, '<td valign="top">The cropping on this doesn''t work for me....just a little too tight on the top.  You did choose an interesting subject, though.</td>', 'The cropping on this doesn''t work for me....just a little too tight on the top.  You did choose an interesting subject, though.', '2004-09-20 13:25:56.000000', NULL, 1),
(918198, 105797, 18197, '<td valign="top">Meets the challenge. Good stopped motion. Focus okay. Composition could be improved. Colors make my teeth hurt.</td>', 'Meets the challenge. Good stopped motion. Focus okay. Composition could be improved. Colors make my teeth hurt.', '2004-09-20 13:32:55.000000', NULL, 1),
(918199, 106172, 16488, '<td valign="top">Clever subject!  I like the selective desaturation, but the grass seems a little too yellow.   The title helped me understand the subject, I wonder if more of the wheel were showing if it would have been so necessary.  Luck!</td>', 'Clever subject!  I like the selective desaturation, but the grass seems a little too yellow.   The title helped me understand the subject, I wonder if more of the wheel were showing if it would have been so necessary.  Luck!', '2004-09-20 13:34:11.000000', NULL, 1),
(918202, 105675, 16488, '<td valign="top">What an interesting form this technique created!  Nicely done.</td>', 'What an interesting form this technique created!  Nicely done.', '2004-09-20 13:35:42.000000', NULL, 1),
(918209, 106319, 5822, '<td valign="top">I love the curves in this pic, but wish the white feathers were a bit brighter.</td>', 'I love the curves in this pic, but wish the white feathers were a bit brighter.', '2004-09-20 13:40:26.000000', NULL, 1),
(918211, 105814, 21606, '<td valign="top">I like your depth of field, and the way the bird is lit up more than the background.</td>', 'I like your depth of field, and the way the bird is lit up more than the background.', '2004-09-20 13:42:02.000000', NULL, 1),
