(918288, 106289, 12962, '<td valign="top">Not sure if I can call this stopped motion because obviously there are trailing lights because of the slow shutter speed.  It is obviously a beautiful photograph with beautiful colors and great composition and would place high in any other motion challenges ... but for stopped motion it might not work at least for me.</td>', 'Not sure if I can call this stopped motion because obviously there are trailing lights because of the slow shutter speed.  It is obviously a beautiful photograph with beautiful colors and great composition and would place high in any other motion challenges ... but for stopped motion it might not work at least for me.', '2004-09-20 14:24:18.000000', NULL, 1),
(918290, 106050, 16636, '<td valign="top">interesting idea, but not convinced this works for me</td>', 'interesting idea, but not convinced this works for me', '2004-09-20 14:25:40.000000', NULL, 1),
(918295, 106327, 21606, '<td valign="top">Nice bubbles. The blue is nice, and the stripe of light really adds to it.</td>', 'Nice bubbles. The blue is nice, and the stripe of light really adds to it.', '2004-09-20 14:28:28.000000', NULL, 1),
