(918300, 106315, 21606, '<td valign="top">I like this one because you add something to just the drop by pulling back and letting us see the cup too. Harold Edgerton (the person who first photographed this) would be proud. 10</td>', 'I like this one because you add something to just the drop by pulling back and letting us see the cup too. Harold Edgerton (the person who first photographed this) would be proud. 10', '2004-09-20 14:30:57.000000', NULL, 1),
(918306, 106002, 22964, '<td valign="top">Its the first time I see this nature event. Curious.</td>', 'Its the first time I see this nature event. Curious.', '2004-09-20 14:33:48.000000', NULL, 1),
(918307, 105675, 21606, '<td valign="top">This is a wonderful display of stopped motion! One of the best I''ve seen. Harold Edgerton (the person who first photographed this) would be proud. 10</td>', 'This is a wonderful display of stopped motion! One of the best I''ve seen. Harold Edgerton (the person who first photographed this) would be proud. 10', '2004-09-20 14:33:55.000000', NULL, 1),
(918309, 106183, 21606, '<td valign="top">That''s a lot of fruit. I like the look on his face, it says "I''m not worried about this at all, I got it under control."</td>', 'That''s a lot of fruit. I like the look on his face, it says "I''m not worried about this at all, I got it under control."', '2004-09-20 14:34:52.000000', NULL, 1),
(918317, 105716, 21606, '<td valign="top">Wow! I like how I can see the smoke. Good Stopped action.</td>', 'Wow! I like how I can see the smoke. Good Stopped action.', '2004-09-20 14:39:08.000000', NULL, 1),
(918319, 106366, 23729, '<td valign="top">Really interesting image, very Man Ray looking.  I''d like to know how you got this visual effect.</td>', 'Really interesting image, very Man Ray looking.  I''d like to know how you got this visual effect.', '2004-09-20 14:39:54.000000', NULL, 1),
