INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(918327, 106191, 22781, '<td valign="top">Sorry, but don''t like it. Looks like digital art and the colors of the background hurt my eyes, very sharp, but just not for me (hey, I''m honnest) (6)</td>', 'Sorry, but don''t like it. Looks like digital art and the colors of the background hurt my eyes, very sharp, but just not for me (hey, I''m honnest) (6)', '2004-09-20 14:42:38.000000', NULL, 1),
(918328, 106205, 24454, '<td valign="top">Incredible!</td>', 'Incredible!', '2004-09-20 14:42:51.000000', NULL, 1),
(918330, 106347, 22781, '<td valign="top">Yeah, I had to think for a moment, but now I get it (I hope)<br/>Game is the background, then a few cm higher is a glass plate with the yelow pieces on it.. Am I right? <br/>Looks real! Just a bit oversharpened? 8</td>', 'Yeah, I had to think for a moment, but now I get it (I hope)Game is the background, then a few cm higher is a glass plate with the yelow pieces on it.. Am I right? Looks real! Just a bit oversharpened? 8', '2004-09-20 14:46:03.000000', NULL, 1),
(918333, 106235, 24454, '<td valign="top">Perfect capture!</td>', 'Perfect capture!', '2004-09-20 14:48:05.000000', NULL, 1),
(918334, 106355, 24454, '<td valign="top">Wow!  You certainly captured the essence of the challenge with this one!  It''s a perfect 10!</td>', 'Wow!  You certainly captured the essence of the challenge with this one!  It''s a perfect 10!', '2004-09-20 14:50:59.000000', NULL, 1),
(918335, 105971, 21606, '<td valign="top">Nice framing!</td>', 'Nice framing!', '2004-09-20 14:51:01.000000', NULL, 1),
(918337, 106285, 22734, '<td valign="top">This is certainly a beauty with wonderful colors. Bumping up.</td>', 'This is certainly a beauty with wonderful colors. Bumping up.', '2004-09-20 14:51:47.000000', NULL, 1),
(918344, 106245, 22964, '<td valign="top">Where is the motion?</td>', 'Where is the motion?', '2004-09-20 14:54:29.000000', NULL, 1),
(918345, 106205, 22781, '<td valign="top">One of my 3 ten''s in this competition, let me say that you are my number 3.<br/>Why do I like this picture?<br/>I like the use of negative space with just one simple subject. You did that.<br/>Wish I would have made this :)</td>', 'One of my 3 ten''s in this competition, let me say that you are my number 3.Why do I like this picture?I like the use of negative space with just one simple subject. You did that.Wish I would have made this :)', '2004-09-20 14:54:42.000000', NULL, 1),
(918346, 106309, 22781, '<td valign="top">One of my 3 10''s just because I like elephant''s and this is very original... Different from all others!</td>', 'One of my 3 10''s just because I like elephant''s and this is very original... Different from all others!', '2004-09-20 14:55:26.000000', NULL, 1),
(918347, 105603, 22734, '<td valign="top">Very good capture. I would have used the sky exclusively to deliniate the subject''s figure and then you would have had complete freedom to adjust the levels on the figure. The jump and pose is outstanding. Also, not dead sharp but the comp is strong enough to bump you up to 6.</td>', 'Very good capture. I would have used the sky exclusively to deliniate the subject''s figure and then you would have had complete freedom to adjust the levels on the figure. The jump and pose is outstanding. Also, not dead sharp but the comp is strong enough to bump you up to 6.', '2004-09-20 14:56:13.000000', NULL, 1),
(918349, 105646, 22734, '<td valign="top">Quite a surge and the figure adds interest. Bumping up.</td>', 'Quite a surge and the figure adds interest. Bumping up.', '2004-09-20 14:57:47.000000', NULL, 1),
(918350, 105716, 22734, '<td valign="top">Good stop action with cool lighting. Bumping up.</td>', 'Good stop action with cool lighting. Bumping up.', '2004-09-20 14:58:54.000000', NULL, 1),
(918351, 106287, 22964, '<td valign="top">Where is the surfer?</td>', 'Where is the surfer?', '2004-09-20 15:01:07.000000', NULL, 1),
(918354, 106136, 22734, '<td valign="top">This little guy is so cool and look at his superb concentration. Not the very best, but certainly the most endearing image of this challenge and deserving a super bump.</td>', 'This little guy is so cool and look at his superb concentration. Not the very best, but certainly the most endearing image of this challenge and deserving a super bump.', '2004-09-20 15:01:47.000000', NULL, 1),
(918355, 105791, 22964, '<td valign="top">Beautiful milk. Somewhat dirty image.</td>', 'Beautiful milk. Somewhat dirty image.', '2004-09-20 15:02:01.000000', NULL, 1),
(918357, 105704, 22734, '<td valign="top">Great action shot. Bumping up. I know, this was a hard capture with the limited light, but you brought us the essence. Bumping up.</td>', 'Great action shot. Bumping up. I know, this was a hard capture with the limited light, but you brought us the essence. Bumping up.', '2004-09-20 15:04:33.000000', NULL, 1),
(918359, 106191, 22964, '<td valign="top">Original, but background too artificial.</td>', 'Original, but background too artificial.', '2004-09-20 15:06:47.000000', NULL, 1),
(918362, 106082, 24911, '<td valign="top">Would have been a much better shop if we could see them from the front, or see  their faces...</td>', 'Would have been a much better shop if we could see them from the front, or see  their faces...', '2004-09-20 15:07:26.000000', NULL, 1),
(918365, 106183, 10763, '<td valign="top">Wow! Great Shot!!!</td>', 'Wow! Great Shot!!!', '2004-09-20 20:19:59.000000', NULL, 1),
(918374, 105675, 15768, '<td valign="top">great capture!</td>', 'great capture!', '2004-09-20 20:28:59.000000', NULL, 1),
(918377, 106111, 3697, '<td valign="top">While there is a significant number of water drop shots in this challenge, I think this is one of (if not the) best of the bunch. Great composition and color, and the clarity is superb.</td>', 'While there is a significant number of water drop shots in this challenge, I think this is one of (if not the) best of the bunch. Great composition and color, and the clarity is superb.', '2004-09-20 20:31:32.000000', NULL, 1),
(918382, 106000, 3697, '<td valign="top">Very nice catch :)</td>', 'Very nice catch :)', '2004-09-20 20:33:25.000000', NULL, 1),
(918385, 106208, 3697, '<td valign="top">Wow, talk about perfect timing.</td>', 'Wow, talk about perfect timing.', '2004-09-20 20:34:10.000000', NULL, 1),
(918392, 106309, 16075, '<td valign="top">Very interesting subject matter and beautiful colors.</td>', 'Very interesting subject matter and beautiful colors.', '2004-09-20 20:40:45.000000', NULL, 1),
(918398, 106327, 3697, '<td valign="top">Great clarity, and composition but it''s the great blue toning that really caught my eye.</td>', 'Great clarity, and composition but it''s the great blue toning that really caught my eye.', '2004-09-20 20:45:08.000000', NULL, 1),
(918399, 106327, 11518, '<td valign="top">Beautiful.  Were you really scuba diving or was this set up in a fish tank?  In any case this is very well done. 10</td>', 'Beautiful.  Were you really scuba diving or was this set up in a fish tank?  In any case this is very well done. 10', '2004-09-20 20:45:32.000000', NULL, 1),
(918400, 106285, 16075, '<td valign="top">I absolutely love hot air balloons and their magnificent colors, I just don''t think of them as very action packed.  This is a nice photo but would better be appreciated in a different challenge.</td>', 'I absolutely love hot air balloons and their magnificent colors, I just don''t think of them as very action packed.  This is a nice photo but would better be appreciated in a different challenge.', '2004-09-20 20:47:18.000000', NULL, 1),
(918409, 106326, 16075, '<td valign="top">I''m so tired of seeing stop motion water droplets.  At least you added something of interest in the photo.  I give you extra credit for that.</td>', 'I''m so tired of seeing stop motion water droplets.  At least you added something of interest in the photo.  I give you extra credit for that.', '2004-09-20 20:53:02.000000', NULL, 1),
(918411, 106347, 16075, '<td valign="top">too blurry</td>', 'too blurry', '2004-09-20 20:55:46.000000', NULL, 1),
(918415, 106054, 16075, '<td valign="top">Addition of beautiful colors earned this familiar subject matter extra points.</td>', 'Addition of beautiful colors earned this familiar subject matter extra points.', '2004-09-20 20:57:56.000000', NULL, 1),
(918417, 106290, 16075, '<td valign="top">If only the helmet wasn''t on the very top edge of this photo, the would have been a wonderful shot.  you still did a great job of stopping the action.</td>', 'If only the helmet wasn''t on the very top edge of this photo, the would have been a wonderful shot.  you still did a great job of stopping the action.', '2004-09-20 20:59:52.000000', NULL, 1),
(918423, 106053, 16075, '<td valign="top">This is great...very interesting subject matter.</td>', 'This is great...very interesting subject matter.', '2004-09-20 21:02:55.000000', NULL, 1),
(918432, 106191, 16075, '<td valign="top">I don''t know why but this looks very phony to me.</td>', 'I don''t know why but this looks very phony to me.', '2004-09-20 21:10:31.000000', NULL, 1),
(918434, 105886, 16075, '<td valign="top">Too grainy looking.</td>', 'Too grainy looking.', '2004-09-20 21:11:36.000000', NULL, 1),
(918441, 106243, 16075, '<td valign="top">Best stopped motion bird shot I have seen in this challenge so far.</td>', 'Best stopped motion bird shot I have seen in this challenge so far.', '2004-09-20 21:14:31.000000', NULL, 1),
(918449, 105988, 13091, '<td valign="top">Bonne idée. Very sharp. 7</td>', 'Bonne idée. Very sharp. 7', '2004-09-20 21:18:18.000000', NULL, 1),
(918455, 106183, 16075, '<td valign="top">I like your theme.  I think it is very clever.  While this shot is very clear and very colorful, something bothers me about it.  I don''t know if it is too bright or what.  It doesn''t look like the fruit could really be in those positions naturally.  It looks to me like they must have been added onto the picture later or something.  I''m not saying you did that, but that is the impression I get from it.</td>', 'I like your theme.  I think it is very clever.  While this shot is very clear and very colorful, something bothers me about it.  I don''t know if it is too bright or what.  It doesn''t look like the fruit could really be in those positions naturally.  It looks to me like they must have been added onto the picture later or something.  I''m not saying you did that, but that is the impression I get from it.', '2004-09-20 21:23:29.000000', NULL, 1),
