(919089, 106182, 23300, '<td valign="top">The black and white treatment and general composition seperate this from the other images of this type in this challenge. I like the contrast between the straight lines in the background and the curves of the splash. I also think that the tonal contrast in this image is very pleasing.</td>', 'The black and white treatment and general composition seperate this from the other images of this type in this challenge. I like the contrast between the straight lines in the background and the curves of the splash. I also think that the tonal contrast in this image is very pleasing.', '2004-09-21 07:14:12.000000', NULL, 1),
(919091, 106321, 23300, '<td valign="top">Beautiful. This is a compelling image. The black and white treatment is beautiful and the cropping works well too.</td>', 'Beautiful. This is a compelling image. The black and white treatment is beautiful and the cropping works well too.', '2004-09-21 07:18:50.000000', NULL, 1),
(919092, 106123, 23300, '<td valign="top">I like the sense of gravity that you have managed to create.</td>', 'I like the sense of gravity that you have managed to create.', '2004-09-21 07:19:39.000000', NULL, 1),
(919093, 106340, 23300, '<td valign="top">The composition is powerful and really enhances the frantic nature of the race.</td>', 'The composition is powerful and really enhances the frantic nature of the race.', '2004-09-21 07:20:34.000000', NULL, 1),
