(919564, 105171, 22734, '<td valign="top">This meets and surpasses the challenge. My question is: was it thrown in the direction it is travelling or was it thrown up from the bottom? Either way, you get bumped upwards. Good image.</td>', 'This meets and surpasses the challenge. My question is: was it thrown in the direction it is travelling or was it thrown up from the bottom? Either way, you get bumped upwards. Good image.', '2004-09-21 14:58:20.000000', NULL, 1),
(919571, 105723, 22734, '<td valign="top">This is both good and funny. Bumping up.</td>', 'This is both good and funny. Bumping up.', '2004-09-21 15:03:21.000000', NULL, 1),
(919572, 105653, 16301, '<td valign="top">This is a REALLY great and original idea! Very very well executed! Let me guess, graphicfunk? (10)<br/> <br/>Good luck...</td>', 'This is a REALLY great and original idea! Very very well executed! Let me guess, graphicfunk? (10) Good luck...', '2004-09-21 15:04:04.000000', NULL, 1),
