(920206, 106055, 27120, '<td valign="top">I love this photo, the emotion portrayed through this shattered inanimate object is awesome.</td>', 'I love this photo, the emotion portrayed through this shattered inanimate object is awesome.', '2004-09-21 23:03:49.000000', NULL, 1),
(920219, 106164, 22734, '<td valign="top">Flavor of an old time photo. Bumping up to 9 for subject and locale selection.</td>', 'Flavor of an old time photo. Bumping up to 9 for subject and locale selection.', '2004-09-21 23:20:57.000000', NULL, 1),
(920243, 105307, 23338, '<td valign="top">I don''t know is this is stopped motion or not - but the image is absolutely wonderful with the bright brown violin contrasting with the shades of gray throughout the rest of the image.  The composition is super.  I''d give it an even higher rating if it was for a "3 Cs" challenge (color, contrast and composition).   There''s humour somewhere in there.  Anyway, if you don''t mind, I''ll make this one of my "favorites".  Good luck with the challenge.</td>', 'I don''t know is this is stopped motion or not - but the image is absolutely wonderful with the bright brown violin contrasting with the shades of gray throughout the rest of the image.  The composition is super.  I''d give it an even higher rating if it was for a "3 Cs" challenge (color, contrast and composition).   There''s humour somewhere in there.  Anyway, if you don''t mind, I''ll make this one of my "favorites".  Good luck with the challenge.', '2004-09-21 23:32:32.000000', NULL, 1),
(920248, 106355, 23338, '<td valign="top">Oh, man!  That is just so graceful!  And normally, such a background would be distracting, but it really highlights the white pants.  Even their belts are a part of the "dance".   Good focus; nice stop.  Congratulations and good luck with the challenge.</td>', 'Oh, man!  That is just so graceful!  And normally, such a background would be distracting, but it really highlights the white pants.  Even their belts are a part of the "dance".   Good focus; nice stop.  Congratulations and good luck with the challenge.', '2004-09-21 23:34:50.000000', NULL, 1),
(920258, 106017, 23338, '<td valign="top">"Left 45 degrees, down 5 feet, proceed visually and contact ground (water?) control on channel 1143" - or something like that.  :-)  That image is so cool.   This duck looks like he''s been through the mill though.  Feathers rather worn here and there.  All of which we wouldn''t know except you stopped him cold - with great focus.  Good capture.  Congratulations and good luck with the challenge.</td>', '"Left 45 degrees, down 5 feet, proceed visually and contact ground (water?) control on channel 1143" - or something like that.  :-)  That image is so cool.   This duck looks like he''s been through the mill though.  Feathers rather worn here and there.  All of which we wouldn''t know except you stopped him cold - with great focus.  Good capture.  Congratulations and good luck with the challenge.', '2004-09-21 23:39:55.000000', NULL, 1),
(920264, 106183, 23338, '<td valign="top">You really stopped the movement.  And cought the color.  And the composition.  Sure you don''t have "juggle" in your name?  Did someone else toss additional objects into the mix?  Regardless - shows great skill.  Congratulations and good luck with the challenge.</td>', 'You really stopped the movement.  And cought the color.  And the composition.  Sure you don''t have "juggle" in your name?  Did someone else toss additional objects into the mix?  Regardless - shows great skill.  Congratulations and good luck with the challenge.', '2004-09-21 23:45:03.000000', NULL, 1),
(920270, 105653, 23338, '<td valign="top">Interesting approach.   How many times did you need to hit the board to get them composed like that?  The contrast between the natural browns and green against the black background is very attractive.   Really like the image.  Good luck with the challenge.</td>', 'Interesting approach.   How many times did you need to hit the board to get them composed like that?  The contrast between the natural browns and green against the black background is very attractive.   Really like the image.  Good luck with the challenge.', '2004-09-21 23:47:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(920273, 105515, 23338, '<td valign="top">I did some shots like this once, but they were a little early for this challenge - over forty years ago on the west coast of France.  Anyway, spectacular lighting, really great action, stopped it nicely.  Wish there was a tad more focus in places; just seems kind of soft.  Just the same, congratulations.  Nice image.</td>', 'I did some shots like this once, but they were a little early for this challenge - over forty years ago on the west coast of France.  Anyway, spectacular lighting, really great action, stopped it nicely.  Wish there was a tad more focus in places; just seems kind of soft.  Just the same, congratulations.  Nice image.', '2004-09-21 23:49:47.000000', NULL, 1),
(920281, 106172, 4494, '<td valign="top">Pretty creative... did you have someone drop the blades down?  There''s some white specks on the right side that you should have cloned out, but pretty good!</td>', 'Pretty creative... did you have someone drop the blades down?  There''s some white specks on the right side that you should have cloned out, but pretty good!', '2004-09-21 23:56:48.000000', NULL, 1),
(920286, 106194, 4494, '<td valign="top">Cool, the blade looks perfectly frozen.  Good job.</td>', 'Cool, the blade looks perfectly frozen.  Good job.', '2004-09-22 00:02:55.000000', NULL, 1),
(920287, 106122, 24976, '<td valign="top">amazing, i love the mood and the smoothness and sharpness. the timing and composition are very masterfully executed.</td>', 'amazing, i love the mood and the smoothness and sharpness. the timing and composition are very masterfully executed.', '2004-09-22 00:03:08.000000', NULL, 1),
(920289, 105675, 4494, '<td valign="top">Very cool... you are one of the lucky ones who have the gadget to snap the shot on sound or something.  I love these!  Great!  And well done as well.</td>', 'Very cool... you are one of the lucky ones who have the gadget to snap the shot on sound or something.  I love these!  Great!  And well done as well.', '2004-09-22 00:05:25.000000', NULL, 1),
(920293, 105499, 24976, '<td valign="top">just wishing the sky wasnt white...</td>', 'just wishing the sky wasnt white...', '2004-09-22 00:06:44.000000', NULL, 1),
(920297, 106097, 24976, '<td valign="top">beautiful, so much feeling and emotion is carried in this simple photo. the colors are excellent, the composition is masterfull. and you captures the true essense of motion, a golden red leaf blowing in the fall wind. perfect. 10</td>', 'beautiful, so much feeling and emotion is carried in this simple photo. the colors are excellent, the composition is masterfull. and you captures the true essense of motion, a golden red leaf blowing in the fall wind. perfect. 10', '2004-09-22 00:09:18.000000', NULL, 1),
(920298, 106183, 4494, '<td valign="top">What the...!!??  That''s really cool, hope you mention how you did it.  You should have thrown in a Big Mac.  Oops that wouldn''t be healthy then... :D</td>', 'What the...!!??  That''s really cool, hope you mention how you did it.  You should have thrown in a Big Mac.  Oops that wouldn''t be healthy then... :D', '2004-09-22 00:09:40.000000', NULL, 1),
(920300, 106148, 4494, '<td valign="top">What is this?  Looks like a ballon that was filled with smoke?  Very interesting.</td>', 'What is this?  Looks like a ballon that was filled with smoke?  Very interesting.', '2004-09-22 00:11:47.000000', NULL, 1),
(920308, 106328, 4494, '<td valign="top">Love the sharp focus on water/bird, and then the extremely blurry upper part.  Great colors.  Perfect exposure.</td>', 'Love the sharp focus on water/bird, and then the extremely blurry upper part.  Great colors.  Perfect exposure.', '2004-09-22 00:15:32.000000', NULL, 1),
