(923383, 106293, 19608, '<td valign="top">What PERFECT timing.  Looks like a mirror image.  You''ve pulled off a masterpiece that will finish in the stratosphere!</td>', 'What PERFECT timing.  Looks like a mirror image.  You''ve pulled off a masterpiece that will finish in the stratosphere!', '2004-09-23 13:05:19.000000', NULL, 1),
(923395, 105603, 10047, '<td valign="top">Might have tried for a horizontal crop, but I don''t know what you had to work with. The photo has energy, and I think it would have had more impact facing  the sun as to bring out the expressionthe face.</td>', 'Might have tried for a horizontal crop, but I don''t know what you had to work with. The photo has energy, and I think it would have had more impact facing  the sun as to bring out the expressionthe face.', '2004-09-23 13:15:56.000000', NULL, 1),
(923399, 106261, 10047, '<td valign="top">I think I would have liked to see the pitcher in focus rather than the batter. The batter although well focused seems to be waiting and not in motion.</td>', 'I think I would have liked to see the pitcher in focus rather than the batter. The batter although well focused seems to be waiting and not in motion.', '2004-09-23 13:17:56.000000', NULL, 1),
(923401, 105562, 10047, '<td valign="top">Hope he is not as ferocious as he looks. Nice shot and good lighting.</td>', 'Hope he is not as ferocious as he looks. Nice shot and good lighting.', '2004-09-23 13:19:53.000000', NULL, 1),
(923404, 106111, 5822, '<td valign="top">A nice bit of color contrast for a hackneyed subject. Very good capture of the drop and I like the water tones as well.</td>', 'A nice bit of color contrast for a hackneyed subject. Very good capture of the drop and I like the water tones as well.', '2004-09-23 13:23:29.000000', NULL, 1),
