(923845, 106208, 24896, '<td valign="top">Very cool pic..I love how the water comes up between her arms and legs...I think some fill flash would have helped but still great. and a fitting title too. lol</td>', 'Very cool pic..I love how the water comes up between her arms and legs...I think some fill flash would have helped but still great. and a fitting title too. lol', '2004-09-23 19:02:35.000000', NULL, 1),
(923920, 105603, 509, '<td valign="top">A horizontal crop would probably fit this better.</td>', 'A horizontal crop would probably fit this better.', '2004-09-23 19:42:22.000000', NULL, 1),
(923939, 106187, 21643, '<td valign="top">Excellent photo! I''m sure some will not see this one as a stopped motion shot, but I''ve had many fish and tried to photograph them. I know how difficult it is to get the proper lighting much less stop the motion. To have the "fluttering" fins stopped rather than blurred and the mouth open like this is outstanding. Congratulations on this shot and best of luck in the challenge!</td>', 'Excellent photo! I''m sure some will not see this one as a stopped motion shot, but I''ve had many fish and tried to photograph them. I know how difficult it is to get the proper lighting much less stop the motion. To have the "fluttering" fins stopped rather than blurred and the mouth open like this is outstanding. Congratulations on this shot and best of luck in the challenge!', '2004-09-23 19:59:21.000000', NULL, 1),
(923952, 106347, 21643, '<td valign="top">Exceptional photograph! I am impressed by the originality, composition, degree of difficulty, and end result! I would expect a ribbon on this one. Great work!</td>', 'Exceptional photograph! I am impressed by the originality, composition, degree of difficulty, and end result! I would expect a ribbon on this one. Great work!', '2004-09-23 20:10:06.000000', NULL, 1),
