(924001, 106002, 3936, '<td valign="top">The background and the ropes compete with the image.  Perhaps a bit more contrast would help the bubble stand out.  I know you were also fighting the steam which makes contrast and sharpness look low.  Howver, the bubble abouit to burst is really a good catch.  6</td>', 'The background and the ropes compete with the image.  Perhaps a bit more contrast would help the bubble stand out.  I know you were also fighting the steam which makes contrast and sharpness look low.  Howver, the bubble abouit to burst is really a good catch.  6', '2004-09-23 20:52:11.000000', NULL, 1),
(924002, 105534, 22734, '<td valign="top">This is a lovely image with the droplets falling. A great image to enhance a top notch port. Bumping up.</td>', 'This is a lovely image with the droplets falling. A great image to enhance a top notch port. Bumping up.', '2004-09-23 20:52:20.000000', NULL, 1),
(924004, 106208, 22734, '<td valign="top">This is indeed a fun shot. Very well executed abd a delight to see and enjoy. Bumping up.</td>', 'This is indeed a fun shot. Very well executed abd a delight to see and enjoy. Bumping up.', '2004-09-23 20:53:30.000000', NULL, 1),
(924006, 106182, 22734, '<td valign="top">beautiful and good b/w choice. Very sharp and clear. Bumping up.</td>', 'beautiful and good b/w choice. Very sharp and clear. Bumping up.', '2004-09-23 20:54:34.000000', NULL, 1),
(924009, 106148, 3936, '<td valign="top">Interesting, how many tries did it take to catch it?</td>', 'Interesting, how many tries did it take to catch it?', '2004-09-23 21:00:35.000000', NULL, 1),
(924010, 105675, 3936, '<td valign="top">Impressive capture.  9</td>', 'Impressive capture.  9', '2004-09-23 21:02:07.000000', NULL, 1),
(924011, 105307, 22734, '<td valign="top">Very interesting effect and excellent use of desat. A variation on this idea is to have had only a single place for the eye to land and that is the instrument, by toning down the the left hand. Nevertheless, the instrument is coming right out and the background is great. Bumping up to 7</td>', 'Very interesting effect and excellent use of desat. A variation on this idea is to have had only a single place for the eye to land and that is the instrument, by toning down the the left hand. Nevertheless, the instrument is coming right out and the background is great. Bumping up to 7', '2004-09-23 21:02:22.000000', NULL, 1),
(924018, 106150, 24681, '<td valign="top">This is  beautiful. Especially the reflection in the drops.</td>', 'This is  beautiful. Especially the reflection in the drops.', '2004-09-23 21:09:06.000000', NULL, 1),
(924029, 105316, 24681, '<td valign="top">Brilliant colors!! I don''t know how you did it, but it seems more like a glass sculpture than anything "liquidy" simply beautiful! If I could vote you would have gotten an 11!</td>', 'Brilliant colors!! I don''t know how you did it, but it seems more like a glass sculpture than anything "liquidy" simply beautiful! If I could vote you would have gotten an 11!', '2004-09-23 21:14:08.000000', NULL, 1),
(924057, 105855, 22689, '<td valign="top">Fantastic shot !</td>', 'Fantastic shot !', '2004-09-23 21:28:13.000000', NULL, 1),
(924072, 106355, 22689, '<td valign="top">Very interesting composition ! Would like to have alook at your outtakes ...</td>', 'Very interesting composition ! Would like to have alook at your outtakes ...', '2004-09-23 21:35:34.000000', NULL, 1),
(924146, 106242, 509, '<td valign="top">Interesting shot. The border is a bit distracting imho.  The blue coloring is very powerful.</td>', 'Interesting shot. The border is a bit distracting imho.  The blue coloring is very powerful.', '2004-09-23 22:48:28.000000', NULL, 1),
(924148, 105730, 509, '<td valign="top">Excellent capture.  Another interesting take on this could be to take 2 shots, this one and one of the club swing (showing motion blur) and combine the two.  I dunno, I just think it would be cool (aside from the challenge).  I like the depth of field.</td>', 'Excellent capture.  Another interesting take on this could be to take 2 shots, this one and one of the club swing (showing motion blur) and combine the two.  I dunno, I just think it would be cool (aside from the challenge).  I like the depth of field.', '2004-09-23 22:50:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(924152, 106340, 509, '<td valign="top">Definitely a different sort of race = )<br/>I like the originality and the angle of composition used.  I might have either increased the exposure (up the ISO) in shooting or lighten it up a bit in post processing to add some contrast</td>', 'Definitely a different sort of race = )I like the originality and the angle of composition used.  I might have either increased the exposure (up the ISO) in shooting or lighten it up a bit in post processing to add some contrast', '2004-09-23 22:53:17.000000', NULL, 1),
(924245, 106178, 24846, '<td valign="top">Very cool. Lookng forward to how you shot this.</td>', 'Very cool. Lookng forward to how you shot this.', '2004-09-24 00:04:25.000000', NULL, 1),
(924248, 106332, 24846, '<td valign="top">Love the composition of "generation" of war aviators. While the jet craft moves forward, that "stop motion" of the RF propeller is definining of your image.</td>', 'Love the composition of "generation" of war aviators. While the jet craft moves forward, that "stop motion" of the RF propeller is definining of your image.', '2004-09-24 00:08:27.000000', NULL, 1),
(924250, 106347, 14001, '<td valign="top">I personally would liked to have seen all the pieces in focus.  Lots of work the set that up!</td>', 'I personally would liked to have seen all the pieces in focus.  Lots of work the set that up!', '2004-09-24 00:09:22.000000', NULL, 1),
(924251, 106183, 12253, '<td valign="top">I really love this photo.  I think this is the best use of stop motion shooting I''ve seen in the contest, and so I am awarding you my first place pick.   The moment in time you captured in time is just perfect.  I think having this in bright sunlight, while looking good on the veggies though, is one small weaknes on the person.  But overall, this photo works very well, so you get a 10!</td>', 'I really love this photo.  I think this is the best use of stop motion shooting I''ve seen in the contest, and so I am awarding you my first place pick.   The moment in time you captured in time is just perfect.  I think having this in bright sunlight, while looking good on the veggies though, is one small weaknes on the person.  But overall, this photo works very well, so you get a 10!', '2004-09-24 00:10:29.000000', NULL, 1),
(924253, 105775, 24846, '<td valign="top">Neat.  Love the sepia, crop, and the stop of the bubble in front of the potted plant.</td>', 'Neat.  Love the sepia, crop, and the stop of the bubble in front of the potted plant.', '2004-09-24 00:11:01.000000', NULL, 1),
(924254, 106096, 24846, '<td valign="top">Looks a little frisky...</td>', 'Looks a little frisky...', '2004-09-24 00:11:27.000000', NULL, 1),
(924257, 105762, 24846, '<td valign="top">Creative... great stop. color, composition...</td>', 'Creative... great stop. color, composition...', '2004-09-24 00:12:40.000000', NULL, 1),
(924261, 106111, 24846, '<td valign="top">I''ll say it again, I love the water drops, each unique. This is particular grabbing with the color, and crop. The main drop on top really pulls me in...great shot.</td>', 'I''ll say it again, I love the water drops, each unique. This is particular grabbing with the color, and crop. The main drop on top really pulls me in...great shot.', '2004-09-24 00:16:05.000000', NULL, 1),
(924265, 105646, 25364, '<td valign="top">red is good on all pictures, this one is  excellent with the "watermonster"</td>', 'red is good on all pictures, this one is  excellent with the "watermonster"', '2004-09-24 00:17:38.000000', NULL, 1),
(924267, 106355, 24846, '<td valign="top">Wonderful shot from background, facial expressions, and colors...</td>', 'Wonderful shot from background, facial expressions, and colors...', '2004-09-24 00:18:09.000000', NULL, 1),
(924270, 106261, 24846, '<td valign="top">With same age kids in baseball I always love these shots, harder than peolple think. I had a similar one submitted but chose an informal football field goal shot instead.  Nice dof, good capture of the stitches.</td>', 'With same age kids in baseball I always love these shots, harder than peolple think. I had a similar one submitted but chose an informal football field goal shot instead.  Nice dof, good capture of the stitches.', '2004-09-24 00:21:28.000000', NULL, 1),
(924281, 105988, 24846, '<td valign="top">What a great natural shot. You must work in advertising...Great compostion, dof, color. Distratcted by mirror lines below containors. Should''ve thrown in some coffee in  the cup. -8-</td>', 'What a great natural shot. You must work in advertising...Great compostion, dof, color. Distratcted by mirror lines below containors. Should''ve thrown in some coffee in  the cup. -8-', '2004-09-24 00:27:07.000000', NULL, 1),
(924287, 106173, 24846, '<td valign="top">Neat everything, color reflection, break in stream. I really like how the gel is caught at the spout. Did you capture it hitting? -8-</td>', 'Neat everything, color reflection, break in stream. I really like how the gel is caught at the spout. Did you capture it hitting? -8-', '2004-09-24 00:30:09.000000', NULL, 1),
(924288, 106315, 24846, '<td valign="top"></td>', '', '2004-09-24 00:31:24.000000', NULL, 1),
(924291, 106164, 24846, '<td valign="top">A ribbon contender. The street play is great. Multiple stops of girl, boy, shadow. Despite only the boy''s head in view, I can feel his smile. -9-</td>', 'A ribbon contender. The street play is great. Multiple stops of girl, boy, shadow. Despite only the boy''s head in view, I can feel his smile. -9-', '2004-09-24 00:34:11.000000', NULL, 1),
(924292, 106293, 24846, '<td valign="top">Gosh, how much perfect could this be...</td>', 'Gosh, how much perfect could this be...', '2004-09-24 00:35:29.000000', NULL, 1),
(924295, 106148, 24846, '<td valign="top">Different. I''m always amazed at the creativity of dpc''ers. I would''ve liked her eyes open, but hey what work it must have been. .-7-</td>', 'Different. I''m always amazed at the creativity of dpc''ers. I would''ve liked her eyes open, but hey what work it must have been. .-7-', '2004-09-24 00:38:38.000000', NULL, 1),
(924301, 106010, 24846, '<td valign="top">Ohhh, definitely an explosive capture. Love the colors, angles, and light. Let us know how you blew it up...if other then the title, and I''m sure you swept up the mess.</td>', 'Ohhh, definitely an explosive capture. Love the colors, angles, and light. Let us know how you blew it up...if other then the title, and I''m sure you swept up the mess.', '2004-09-24 00:42:23.000000', NULL, 1),
(924305, 106225, 24846, '<td valign="top">J.C. incarnated. Beautiful, what patience to get this shot. Love the fan of the tail, color, reflection , drop stopped in water on back of right foot. -9-</td>', 'J.C. incarnated. Beautiful, what patience to get this shot. Love the fan of the tail, color, reflection , drop stopped in water on back of right foot. -9-', '2004-09-24 00:46:20.000000', NULL, 1),
(924306, 106290, 24846, '<td valign="top">Good stop, I can count the spokes...</td>', 'Good stop, I can count the spokes...', '2004-09-24 00:47:14.000000', NULL, 1),
(924308, 105534, 24846, '<td valign="top">Lovely, should be a DNR duck stamp. The droplets caught are superb...</td>', 'Lovely, should be a DNR duck stamp. The droplets caught are superb...', '2004-09-24 00:49:08.000000', NULL, 1),
(924309, 106004, 24846, '<td valign="top">Neat. Like the symmetry...</td>', 'Neat. Like the symmetry...', '2004-09-24 00:50:41.000000', NULL, 1),
