(926410, 105791, 3936, '<td valign="top">Love the contrast between the berry and the cream.  9</td>', 'Love the contrast between the berry and the cream.  9', '2004-09-26 02:39:18.000000', NULL, 1),
(926416, 106366, 9906, '<td valign="top">GeneralE?  At first I was gonna mark this a lot lower than I''m thinking now....  I usually don''t like shots that are processed as much as this one seems to be.  Then I thought about how I sometimes feel just like this...   When I look at this, I see a conflict between restraint and rage and this time, rage wins.<br/>You''re right on the edge with this one.  Hope it does well, but doesn''t cause a digital art border fight.<br/>TC</td>', 'GeneralE?  At first I was gonna mark this a lot lower than I''m thinking now....  I usually don''t like shots that are processed as much as this one seems to be.  Then I thought about how I sometimes feel just like this...   When I look at this, I see a conflict between restraint and rage and this time, rage wins.You''re right on the edge with this one.  Hope it does well, but doesn''t cause a digital art border fight.TC', '2004-09-26 02:52:22.000000', NULL, 1),
(926418, 106055, 9906, '<td valign="top">Is Kiwi playing with light bulbs again?<br/>TC</td>', 'Is Kiwi playing with light bulbs again?TC', '2004-09-26 02:55:46.000000', NULL, 1),
(926463, 105971, 22046, '<td valign="top">I really like the graphic feel of this photo. The shaded color of the sky with the bright balloons against it is very very nice.</td>', 'I really like the graphic feel of this photo. The shaded color of the sky with the bright balloons against it is very very nice.', '2004-09-26 04:13:24.000000', NULL, 1),
(926464, 106208, 22046, '<td valign="top">Very funny title and good idea. This really works. How many times did she have to fall into the pool for you to get this shot?</td>', 'Very funny title and good idea. This really works. How many times did she have to fall into the pool for you to get this shot?', '2004-09-26 04:14:34.000000', NULL, 1),
(926465, 106173, 22046, '<td valign="top">Gloop! Three things make this work for me: the sharp focus, the simple design and the great color. Very good work.</td>', 'Gloop! Three things make this work for me: the sharp focus, the simple design and the great color. Very good work.', '2004-09-26 04:15:47.000000', NULL, 1),
(926466, 106238, 22046, '<td valign="top">I can see the fire move... and feel the heat. I love the color in this  and the composition. Good one.</td>', 'I can see the fire move... and feel the heat. I love the color in this  and the composition. Good one.', '2004-09-26 04:16:52.000000', NULL, 1),
(926467, 106111, 22046, '<td valign="top">Clever idea to drop red ink (or food color) into water. Really adds interest to this drop photo.</td>', 'Clever idea to drop red ink (or food color) into water. Really adds interest to this drop photo.', '2004-09-26 04:18:00.000000', NULL, 1),
(926468, 105534, 22046, '<td valign="top">The best of the flying bird photos because of the color and the position of the duck.</td>', 'The best of the flying bird photos because of the color and the position of the duck.', '2004-09-26 04:18:54.000000', NULL, 1),
(926469, 105316, 22046, '<td valign="top">Whatever you used to drop this in sure was colorful. Made this picture work. Beautiful.</td>', 'Whatever you used to drop this in sure was colorful. Made this picture work. Beautiful.', '2004-09-26 04:20:00.000000', NULL, 1),
