INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(927243, 106355, 13381, '<td valign="top">Excellent example of stopped motion.  I''m impressed by the perfect exposure, as well as the flawless figures in mid-air. Great job, and congratulations on your yellow.</td>', 'Excellent example of stopped motion.  I''m impressed by the perfect exposure, as well as the flawless figures in mid-air. Great job, and congratulations on your yellow.', '2004-09-27 01:12:02.000000', NULL, 0),
