(1024796, 106355, 29404, '<td valign="top">grat shot...great</td>', 'grat shot...great', '2004-11-20 20:42:38.000000', NULL, 0),
(1029231, 106111, 10909, '<td valign="top">I like that kind of pics: they give us opportunity to notice the things that last too few... :) But it''s delicious! Mother nature is a real artist :)</td>', 'I like that kind of pics: they give us opportunity to notice the things that last too few... :) But it''s delicious! Mother nature is a real artist :)', '2004-11-23 16:35:29.000000', NULL, 0),
(1033200, 105653, 8860, '<td valign="top">I always meant to comment on this. It''s excellent - very competently shot and a superb answer to the brief. The only thing missing from it is a ribbon!</td>', 'I always meant to comment on this. It''s excellent - very competently shot and a superb answer to the brief. The only thing missing from it is a ribbon!', '2004-11-26 05:18:26.000000', NULL, 0),
(1045063, 105653, 22384, '<td valign="top">(Long speechless pause)... so amazing. You are not only a person who transcends in heart, soul, and spirit; you are an artistic genius. This photo, all of these photos, are breath-taking and awe-inspiring.<br/> <br/>Although it will go against your humble nature, please accept the following praise:<br/> <br/>We all have much to learn from you: in life and in art.<br/> <br/>I wonder if you know how rare you really are: one in a million, no, more like one in a billion. It is an honor to view your work and read your words. Thanks for the balance and the brilliant common sense you bring to this place.<br/> <br/></td>', '(Long speechless pause)... so amazing. You are not only a person who transcends in heart, soul, and spirit; you are an artistic genius. This photo, all of these photos, are breath-taking and awe-inspiring. Although it will go against your humble nature, please accept the following praise: We all have much to learn from you: in life and in art. I wonder if you know how rare you really are: one in a million, no, more like one in a billion. It is an honor to view your work and read your words. Thanks for the balance and the brilliant common sense you bring to this place. ', '2004-12-03 18:43:31.000000', NULL, 0),
(1055444, 106164, 22384, '<td valign="top">Wow! You do a great job of capturing the exuberance of the children in this piece. Great value range and composition. The shadow is masterful!</td>', 'Wow! You do a great job of capturing the exuberance of the children in this piece. Great value range and composition. The shadow is masterful!', '2004-12-10 00:22:43.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1055447, 106164, 22384, '<td valign="top">Xion,<br/>I walked in the room when my mom was commenting on this image. I just had to add my own comment. I LOVE THIS SHOT. It made me smile. Is that a tether ball pole? It brings back memories of when I did this with a friend, and she fell off and almost broke her pinky finger. I know that isn''t funny, but it was still a good time. It is amazing the things we think of, and how fearless we are when we are young. Thanks for this picture and the bringing back the memory.<br/>Bailey</td>', 'Xion,I walked in the room when my mom was commenting on this image. I just had to add my own comment. I LOVE THIS SHOT. It made me smile. Is that a tether ball pole? It brings back memories of when I did this with a friend, and she fell off and almost broke her pinky finger. I know that isn''t funny, but it was still a good time. It is amazing the things we think of, and how fearless we are when we are young. Thanks for this picture and the bringing back the memory.Bailey', '2004-12-10 00:27:48.000000', NULL, 0),
(1056627, 106355, 26117, '<td valign="top">Good shot! Those fighters will be flying for ever.</td>', 'Good shot! Those fighters will be flying for ever.', '2004-12-10 20:42:35.000000', NULL, 0),
