(1299528, 106293, 19708, '<td valign="top">This is an amazing photograph.<br/>Very well seen and at the right place at the right time!<br/></td>', 'This is an amazing photograph.Very well seen and at the right place at the right time!', '2005-04-18 05:22:36.000000', NULL, 0),
(1299716, 106293, 36333, '<td valign="top">Outstanding composition - one of those "once in a lifetime" opportunities.    The birds are a little dark, and the sky is a bit dull, but this would be a killer photo if only the heads were in focus.  No criticism there though - focusing on a moving bird in low light is not easy ;)</td>', 'Outstanding composition - one of those "once in a lifetime" opportunities.    The birds are a little dark, and the sky is a bit dull, but this would be a killer photo if only the heads were in focus.  No criticism there though - focusing on a moving bird in low light is not easy ;)', '2005-04-18 08:28:02.000000', NULL, 0),
(1346984, 106330, 24976, '<td valign="top">i was looking through your portfolio and came across this. I remember this challenge and imo this should have finished way higher than it did.</td>', 'i was looking through your portfolio and came across this. I remember this challenge and imo this should have finished way higher than it did.', '2005-04-30 16:02:49.000000', NULL, 0),
(1415704, 105171, 21862, '<td valign="top">I like this photo, the concept is great.  But I think I am more struck by the strong USM use here... perhaps a little overdone?</td>', 'I like this photo, the concept is great.  But I think I am more struck by the strong USM use here... perhaps a little overdone?', '2005-05-27 11:43:04.000000', NULL, 0),
(1439878, 106187, 36377, '<td valign="top">I have to say the thought of kissing that fish kinda disturbs me but excellent composition and color. My favorite at first glance of your work.<br/><br/><i>Message edited by author 2005-06-08 00:02:09.</i></td>', 'I have to say the thought of kissing that fish kinda disturbs me but excellent composition and color. My favorite at first glance of your work.', '2005-06-08 01:01:21.000000', '2005-06-08 01:02:09.000000', 0),
