(1453773, 106187, 15711, '<td valign="top">Terrific ! !</td>', 'Terrific ! !', '2005-06-14 01:21:20.000000', NULL, 0),
(1491844, 106327, 6388, '<td valign="top">this is another one you should make a print.  very cool.  i wonder how i miss all of these...oh yeah...it''s cuz i don''t look at challenges very often.<br/> <br/>the toning is fabulous...did you do that after the fact or was the B/G actually that awesome blue?</td>', 'this is another one you should make a print.  very cool.  i wonder how i miss all of these...oh yeah...it''s cuz i don''t look at challenges very often. the toning is fabulous...did you do that after the fact or was the B/G actually that awesome blue?', '2005-06-29 14:55:38.000000', NULL, 0),
(1491865, 106327, 34247, '<td valign="top">NICE. I miss diving, and this image is bringing that feeling home. Thanks a lot :)</td>', 'NICE. I miss diving, and this image is bringing that feeling home. Thanks a lot :)', '2005-06-29 15:00:18.000000', NULL, 0),
(1491970, 106327, 1717, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Pedro:</b></div><hr/><i> this is another one you should make a print.  very cool.  i wonder how i miss all of these...oh yeah...it''s cuz i don''t look at challenges very often.<br/> <br/>the toning is fabulous...did you do that after the fact or was the B/G actually that awesome blue? </i></td></tr></table> <br/> <br/>the actual color of the b/g was gold.  i think i used the nik color effects Midnight to tone this. :)</td>', 'Originally posted by Pedro: this is another one you should make a print.  very cool.  i wonder how i miss all of these...oh yeah...it''s cuz i don''t look at challenges very often. the toning is fabulous...did you do that after the fact or was the B/G actually that awesome blue?   the actual color of the b/g was gold.  i think i used the nik color effects Midnight to tone this. :)', '2005-06-29 15:27:05.000000', NULL, 0),
(1518905, 106111, 15711, '<td valign="top">This is great!  You have a true mastery of PS!  I''m still working on it.  Very nice crystal clear shot.  And I love the placement of the drop. (red IS my favorite color)</td>', 'This is great!  You have a true mastery of PS!  I''m still working on it.  Very nice crystal clear shot.  And I love the placement of the drop. (red IS my favorite color)', '2005-07-08 14:31:27.000000', NULL, 0),
(1529462, 105653, 34659, '<td valign="top">WOW!  This is beautiful!  Fantastically composed and executed.  Very ingenious.  I can''t believe how good the DOF is.  I''m very impressed...<br/> <br/>I also have to agree with KDO''s praise.  You are a gem on this site.  Thank you for sharing your art, expertise, and wisdom so generously.</td>', 'WOW!  This is beautiful!  Fantastically composed and executed.  Very ingenious.  I can''t believe how good the DOF is.  I''m very impressed... I also have to agree with KDO''s praise.  You are a gem on this site.  Thank you for sharing your art, expertise, and wisdom so generously.', '2005-07-12 10:21:57.000000', NULL, 0),
